<?php declare(strict_types=1);$data=is_array($data??null)?$data:[];$o=$data['order'];$money=static fn(mixed $v):string=>$o['currency'].' '.number_format((float)$v,2);?>
<div class="sales-workspace"><nav class="card"><a class="btn btn-secondary btn-compact" href="/office_app/public/sales/orders">Back to Sales Orders</a><?php if(!empty($o['quotation_number'])):?><a class="btn btn-secondary btn-compact" href="/office_app/public/sales/quotations/<?=e($o['quotation_id']??'')?>">Quotation <?=e($o['quotation_number'])?></a><?php endif;?></nav><?php \view('components.sales-workflow-trace', ['workflowTrace'=>$data['workflowTrace']??null]); ?><?php if(is_array($data['notice']??null)):?><div class="alert alert-success"><?=e($data['notice']['message']??'')?></div><?php endif;?><?php if(($data['errors']??[])!==[]):?><div class="alert alert-danger"><?php foreach($data['errors'] as $error):?><div><?=e($error)?></div><?php endforeach;?></div><?php endif;?>
<header class="page-header"><div><p class="eyebrow">Sales Order</p><h1><?=e($o['order_number'])?></h1><p class="page-description"><?=e($o['customer_name'])?> · <?=e($o['order_date'])?></p></div></header>
<section class="finance-summary-grid"><article class="card"><span>Order state</span><strong><?=e(strtoupper($o['status']))?></strong></article><article class="card"><span>Delivery state</span><strong><?=e(strtoupper($o['delivery_state']))?></strong></article><article class="card"><span>Invoice state</span><strong><?=e(strtoupper($o['invoice_state']))?></strong></article><article class="card"><span>Payment state</span><strong><?=e(strtoupper($o['payment_state']))?></strong></article></section>
<section class="card"><div class="finance-summary-grid"><div><strong>Customer</strong><p><?=e($o['customer_name'])?></p></div><div><strong>Sales owner</strong><p><?=e($o['agent_name']??'Unassigned')?> · <?=e($o['team_name']??'No team')?></p></div><div><strong>Commercial terms</strong><p><?=e($o['pricelist_name']??'Standard price')?> · <?=e($o['payment_terms_days']??0)?> days</p></div><div><strong>Addresses</strong><p>Billing: <?=e($o['billing_address']??$o['customer_address']??'Not specified')?><br>Delivery: <?=e($o['delivery_address']??$o['customer_address']??'Not specified')?></p></div></div></section>
<section class="card table-card"><div class="table-responsive"><table class="data-table"><thead><tr><th>Product</th><th>Ordered</th><th>Reserved</th><th>Delivered</th><th>Returned</th><th>Net delivered</th><th>Remaining</th><th>Invoiced</th><th>Invoiceable</th><th>Remaining to invoice</th><th>Line total</th></tr></thead><tbody><?php foreach($o['lines'] as $line):?><tr><td><?=e($line['sku'].' - '.$line['description'])?></td><td><?=e($line['quantity'])?></td><td><?=e($line['reserved_quantity'])?></td><td><?=e($line['delivered_quantity'])?></td><td><?=e($line['returned_quantity'])?></td><td><?=e($line['net_delivered_quantity'])?></td><td><?=e($line['remaining_quantity'])?></td><td><?=e($line['invoiced_quantity'])?></td><td><?=e($line['invoiceable_quantity'])?></td><td><?=e($line['remaining_to_invoice'])?></td><td><?=e($money($line['line_total']))?></td></tr><?php endforeach;?></tbody></table></div><div class="table-summary"><span>Untaxed <?=e($money($o['subtotal']-$o['discount_amount']))?> · Tax <?=e($money($o['tax_amount']))?></span><strong>Total <?=e($money($o['total_amount']))?></strong></div></section>
<section class="finance-summary-grid"><article class="card"><h2>Deliveries and returns</h2><?php if($o['pickings']===[]):?><p>No Inventory execution documents.</p><?php endif;?><?php foreach($o['pickings'] as $p):?><p><strong><a href="/office_app/public/sales/deliveries/<?=e($p['picking_id'])?>"><?=e($p['picking_number'])?></a></strong> · <?=e(str_replace('_',' ',$p['picking_type']))?> · <?=e($p['status'])?></p><?php endforeach;?></article><article class="card"><h2>Invoices and payments</h2><?php if($o['invoices']===[]):?><p>No Finance invoices.</p><?php endif;?><?php foreach($o['invoices'] as $i):?><p><strong><a href="/office_app/public/finance/customer-invoices/<?=e($i['invoice_id'])?>"><?=e($i['invoice_number'])?></a></strong> · <?=e(str_replace('_',' ',(string)($i['document_type']??'customer_invoice')))?> · <?=e($i['status'])?> · <?=e($i['payment_status'])?> · residual <?=e($money($i['residual_amount']))?></p><?php endforeach;?><?php if((float)($o['credit_note_eligible_quantity']??0)>0.0005):?><div class="alert alert-warning"><strong>Credit note eligible.</strong> Completed returned quantity remains available for credit.</div><?php endif;?></article></section>
<?php $invoiceable=array_sum(array_map(static fn(array $l)=>(float)$l['invoiceable_quantity'],$o['lines']));$remainingToInvoice=array_sum(array_map(static fn(array $l)=>(float)$l['remaining_to_invoice'],$o['lines']));if(!empty($data['canCreateInvoice'])&&max($invoiceable,$remainingToInvoice)>0):?><section class="card"><h2>Create customer invoice</h2><form method="post" action="/office_app/public/sales/orders/<?=e($o['order_id'])?>/invoices"><?=csrfField()?><label>Invoice policy <select name="invoice_policy"><option value="delivered">Delivered quantities</option><option value="ordered">Ordered quantities</option></select></label><button class="btn btn-primary">Create Invoice</button></form></section><?php endif;?><?php if(!empty($data['canCreateInvoice'])&&(float)($o['credit_note_eligible_quantity']??0)>0.0005):?><section class="card"><h2>Customer return credit</h2><p>Create a separate Finance credit note for the completed returned quantity. Original invoices and payments remain unchanged.</p><form method="post" action="/office_app/public/sales/orders/<?=e($o['order_id'])?>/credit-notes"><?=csrfField()?><button class="btn btn-primary">Create Credit Note</button></form></section><?php endif;?></div>
